//! ASCII-only, byte-wise case transformations.

fn ascii_upper(b: u8) -> u8 {
    if b.is_ascii_lowercase() {
        b - b'a' + b'A'
    } else {
        b
    }
}

fn ascii_lower(b: u8) -> u8 {
    if b.is_ascii_uppercase() {
        b - b'A' + b'a'
    } else {
        b
    }
}

fn camelize_impl(w: &str, upper_first: bool) -> String {
    let mut out = Vec::with_capacity(w.len());
    let mut upper_next = upper_first;
    for &b in w.as_bytes() {
        if b == b'_' {
            upper_next = true;
        } else if upper_next {
            out.push(ascii_upper(b));
            upper_next = false;
        } else {
            out.push(b);
        }
    }
    String::from_utf8(out).unwrap()
}

pub fn camelize(w: &str) -> String {
    camelize_impl(w, false)
}

pub fn camelize_first_upper(w: &str) -> String {
    camelize_impl(w, true)
}

pub fn underscore(w: &str) -> String {
    let mut out = Vec::with_capacity(w.len());
    for (i, &b) in w.as_bytes().iter().enumerate() {
        if b.is_ascii_uppercase() {
            if i > 0 {
                out.push(b'_');
            }
            out.push(ascii_lower(b));
        } else {
            out.push(b);
        }
    }
    String::from_utf8(out).unwrap()
}

pub fn humanize(w: &str) -> String {
    let bytes: Vec<u8> = w
        .as_bytes()
        .iter()
        .map(|&b| if b == b'_' { b' ' } else { b })
        .collect();
    let mut out = bytes;
    if let Some(first) = out.first_mut() {
        *first = ascii_upper(*first);
    }
    String::from_utf8(out).unwrap()
}

pub fn dasherize(w: &str) -> String {
    let out: Vec<u8> = w
        .as_bytes()
        .iter()
        .map(|&b| if b == b'_' { b'-' } else { b })
        .collect();
    String::from_utf8(out).unwrap()
}

pub fn upcase(w: &str) -> String {
    let out: Vec<u8> = w.as_bytes().iter().map(|&b| ascii_upper(b)).collect();
    String::from_utf8(out).unwrap()
}

pub fn downcase(w: &str) -> String {
    let out: Vec<u8> = w.as_bytes().iter().map(|&b| ascii_lower(b)).collect();
    String::from_utf8(out).unwrap()
}

