//! Pluralization-related transformations.

use crate::inflection::case::{camelize_first_upper, underscore};

const UNCOUNTABLES: &[&str] = &[
    "equipment",
    "information",
    "rice",
    "money",
    "species",
    "series",
    "fish",
    "sheep",
    "jeans",
    "police",
];

fn is_uncountable(w: &str) -> bool {
    UNCOUNTABLES.contains(&w)
}

pub fn pluralize(w: &str) -> String {
    if is_uncountable(w) {
        w.to_string()
    } else {
        let mut out = String::with_capacity(w.len() + 1);
        out.push_str(w);
        out.push('s');
        out
    }
}

pub fn singularize(w: &str) -> String {
    if is_uncountable(w) {
        w.to_string()
    } else if w.as_bytes().last() == Some(&b's') {
        w[..w.len() - 1].to_string()
    } else {
        w.to_string()
    }
}

pub fn classify(w: &str) -> String {
    camelize_first_upper(w)
}

pub fn tableize(w: &str) -> String {
    pluralize(&underscore(w))
}

