use inflection::{
    camelize, classify, dasherize, downcase, humanize, pluralize, singularize, tableize,
    underscore, upcase,
};

fn main() {
    for (i, arg) in std::env::args().skip(1).take(4).enumerate() {
        match i {
            0 => {
                println!("{}", pluralize(&arg));
                println!("{}", singularize(&arg));
            }
            1 => {
                println!("{}", camelize(&arg));
                println!("{}", underscore(&arg));
            }
            2 => {
                println!("{}", classify(&arg));
                println!("{}", tableize(&arg));
            }
            3 => {
                println!("{}", humanize(&arg));
                println!("{}", dasherize(&arg));
                println!("{}", upcase(&arg));
                println!("{}", downcase(&arg));
            }
            _ => {}
        }
    }
}

