//! Pluralization-related transformations.
//!
//! All rules are ASCII, byte-wise and case-sensitive (lowercase patterns only),
//! matching the reference C++ inflection library exactly.

use super::case::{camelize_first_upper, underscore};

const UNCOUNTABLES: &[&str] = &[
    "equipment",
    "information",
    "rice",
    "money",
    "species",
    "series",
    "fish",
    "sheep",
    "jeans",
    "police",
];

fn is_uncountable(w: &str) -> bool {
    UNCOUNTABLES.contains(&w)
}

pub fn pluralize(w: &str) -> String {
    if w.is_empty() || is_uncountable(w) {
        w.to_string()
    } else {
        let mut out = String::with_capacity(w.len() + 1);
        out.push_str(w);
        out.push('s');
        out
    }
}

pub fn singularize(w: &str) -> String {
    if w.is_empty() || is_uncountable(w) {
        return w.to_string();
    }
    let b = w.as_bytes();
    let n = b.len();

    // (quiz)zes$ -> \1
    if w.ends_with("quizzes") {
        return w[..n - 3].to_string();
    }
    // (matr)ices$ -> \1ix
    if w.ends_with("matrices") {
        return format!("{}ix", &w[..n - 4]);
    }
    // (vert|ind)ices$ -> \1ex
    if w.ends_with("vertices") || w.ends_with("indices") {
        return format!("{}ex", &w[..n - 4]);
    }
    // ^(ox)en$ -> \1
    if w == "oxen" {
        return "ox".to_string();
    }
    // (alias|status)es$ -> \1
    if w.ends_with("aliases") || w.ends_with("statuses") {
        return w[..n - 2].to_string();
    }
    // (octop|vir)i$ -> \1us
    if w.ends_with("octopi") || w.ends_with("viri") {
        return format!("{}us", &w[..n - 1]);
    }
    // (cris|ax|test)es$ -> \1is
    if w.ends_with("crises") || w.ends_with("axes") || w.ends_with("testes") {
        return format!("{}is", &w[..n - 2]);
    }
    // (o)es$ -> \1
    if w.ends_with("oes") {
        return w[..n - 2].to_string();
    }
    // (bus)es$ -> \1
    if w.ends_with("buses") {
        return w[..n - 2].to_string();
    }
    // ([m|l])ice$ -> \1ouse  (the character class contains a literal '|')
    if n >= 4 && w.ends_with("ice") && matches!(b[n - 4], b'm' | b'l' | b'|') {
        return format!("{}ouse", &w[..n - 3]);
    }
    // (x|ch|ss|sh)es$ -> \1
    if w.ends_with("xes") || w.ends_with("ches") || w.ends_with("sses") || w.ends_with("shes") {
        return w[..n - 2].to_string();
    }
    // ([^aeiouy]|qu)ies$ -> \1y
    if w.ends_with("quies") {
        return format!("{}y", &w[..n - 3]);
    }
    if n >= 4 && w.ends_with("ies") && !matches!(b[n - 4], b'a' | b'e' | b'i' | b'o' | b'u' | b'y')
    {
        return format!("{}y", &w[..n - 3]);
    }
    // ([^f])ves$ -> \1fe
    if n >= 4 && w.ends_with("ves") && b[n - 4] != b'f' {
        return format!("{}fe", &w[..n - 3]);
    }
    // ((a)naly|(b)a|(d)iagno|(p)arenthe|(p)rogno|(s)ynop|(t)he)ses$ -> \1\2sis
    // The second capture group only participates in the "analy" branch, so that
    // branch gets an extra "a" ("analyses" -> "analyasis"), the others plain "sis".
    if n >= 3 && w.ends_with("ses") {
        let stem = &w[..n - 3];
        if stem.ends_with("analy") {
            return format!("{}asis", stem);
        }
        for tail in ["ba", "diagno", "parenthe", "progno", "synop", "the"] {
            if stem.ends_with(tail) {
                return format!("{}sis", stem);
            }
        }
    }
    // ([ti])a$ -> \1um
    if n >= 2 && b[n - 1] == b'a' && matches!(b[n - 2], b't' | b'i') {
        return format!("{}um", &w[..n - 1]);
    }
    // (n)ews$ -> \1ews
    if w.ends_with("news") {
        return w.to_string();
    }
    // s$ -> ""
    if b[n - 1] == b's' {
        return w[..n - 1].to_string();
    }
    w.to_string()
}

pub fn classify(w: &str) -> String {
    camelize_first_upper(&singularize(w))
}

pub fn tableize(w: &str) -> String {
    pluralize(&underscore(w))
}

